def second_smallest_distinct(lst):
    distinct = sorted(set(lst))
    if len(distinct) < 2:
        return None
    return distinct[1]

def second_largest_with_duplicates(lst):
    if len(lst) < 2:
        return None
    s = sorted(lst, reverse=True)
    return s[1]

def kth_largest_distinct(lst, k):
    distinct = sorted(set(lst), reverse=True)
    if k < 1 or k > len(distinct):
        return None
    return distinct[k - 1]

def difference_largest_second_largest(lst):
    if len(lst) < 2:
        return None
    s = sorted(lst, reverse=True)
    return s[0] - s[1]

def balance_index(lst):
    total = sum(lst)
    left = 0
    for i, x in enumerate(lst):
        right = total - left - x
        if left == right:
            return i
        left += x
    return -1

def balance_index_last(lst):
    total = sum(lst)
    left = 0
    result = -1
    for i, x in enumerate(lst):
        right = total - left - x
        if left == right:
            result = i
        left += x
    return result

def is_balanced_list(lst):
    total = sum(lst)
    left = 0
    for x in lst:
        if left == total - left - x:
            return True
        left += x
    return False

def center_of_mass_index(lst):
    total = sum(lst)
    if total == 0:
        return -1
    weighted = sum(i * x for i, x in enumerate(lst))
    return round(weighted / total)

def split_by_threshold(lst, t):
    below = [x for x in lst if x < t]
    at_or_above = [x for x in lst if x >= t]
    return (below, at_or_above)

def split_at_first_negative(lst):
    for i, x in enumerate(lst):
        if x < 0:
            return (lst[:i], lst[i:])
    return (lst[:], [])

def partition_even_odd_values(lst):
    evens = [x for x in lst if x % 2 == 0]
    odds = [x for x in lst if x % 2 != 0]
    return (evens, odds)

def split_before_first_zero(lst):
    for i, x in enumerate(lst):
        if x == 0:
            return (lst[:i], lst[i:])
    return (lst[:], [])

def split_into_runs_by_sign(lst):
    def sign(x):
        if x > 0:
            return 1
        if x < 0:
            return -1
        return 0
    res = []
    for x in lst:
        if res and sign(res[-1][-1]) == sign(x):
            res[-1].append(x)
        else:
            res.append([x])
    return res

def split_by_parity_runs(lst):
    res = []
    for x in lst:
        if res and (res[-1][-1] % 2) == (x % 2):
            res[-1].append(x)
        else:
            res.append([x])
    return res

def unzip_pairs(pairs):
    if not pairs:
        return ([], [])
    firsts = [p[0] for p in pairs]
    seconds = [p[1] for p in pairs]
    return (firsts, seconds)

def pairwise_products(a, b):
    n = min(len(a), len(b))
    return [a[i] * b[i] for i in range(n)]
